import asyncio
import datetime
import adi.AdiClientToRemote
import adi.AdiCommands
import adi.AdiDefinitions
from adi.AdiDefinitions import AdiDataTransferComponent
import adi.AdiEnums

target_host = "192.168.1.50"
dex_to_host = "192.168.1.122"

async def test_dex_list_command():
    loop = asyncio.get_event_loop()
    adi_client = adi.AdiClientToRemote.AdiClientToRemote(loop=loop, host=target_host, realtime=False, minimal_connection=True)
    while adi_client.connection_state != adi.AdiEnums.ConnectionState.CONNECTED:
        await asyncio.sleep(0.1)

    local_host, local_port = adi_client.writer.get_extra_info("sockname")
    print(f"Connected to ADI server from local address {local_host}:{local_port}")

    # Disabled, not limit, 32000, rt_and_stored, continuous, active_well, tables_transfer=False, config_change_notification=True
    # hex_data = bytes.fromhex("")
    # Disabled, limit, 24000, stored_only, continuous, active_run, tables_transfer=True, config_change_notification=False
    # hex_data = bytes.fromhex("")
    # Enabled, limit, 17000, rt_only, continuous, active_well, tables_transfer=True, config_change_notification=True
    # hex_data = bytes.fromhex("")
    # Disabled, not limit, 56000, rt_and_stored, continuous, active_well, tables_transfer=False, config_change_notification=True    # 0x501 - 0101 0000 0001
    hex_data = bytes.fromhex("")
    # Disabled, not limit, 32000, stored_only, one_time_now, active_run, tables_transfer=True, config_change_notification=False     # 0x301 - 0011 0000 0001
    # hex_data = bytes.fromhex("")
    # Disabled, not limit, 32000, stored_only, one_time_at_time, active_run, tables_transfer=True, config_change_notification=False # 0x401 - 0100 0000 0001
    # hex_data = bytes.fromhex("")
    # Disabled, not limit, 32000, stored_only, periodic_at_time, active_run, tables_transfer=True, config_change_notification=False # 0x201 - 0010 0000 0001
    # hex_data = bytes.fromhex("")
    # disabled, not limit, 32000, rt_only, continuous, active_well, tables_transfer=True, config_change_notification=True           # 0x1   - 0000 0000 0001
    # hex_data = bytes.fromhex("")
    # disabled, not limit, 32000, rt_and_stored, continuous, active_well, tables_transfer=True, config_change_notification=True     # 0x501 - 0101 0000 0001
    # hex_data = bytes.fromhex("")
    # enabled, not limit, 32000, stored_only, continuous, active_well, tables_transfer=True, config_change_notification=True        # 0x101 - 0001 0000 0001
    # hex_data = bytes.fromhex("")
    hex_data = bytes.fromhex("")
    component = adi.AdiCommands.AdiCommands.DEX_Add.CreateCommandFromBinaryData(adi_client, adi.AdiDefinitions.MessageHeader(data=hex_data), hex_data).component_dex
    # component.component_text = "Test DEX"

    component:AdiDataTransferComponent = AdiDataTransferComponent(
        id=99,
        remote_host=dex_to_host, data_transfer_enabled=False,
        component_text=f"[TMRigsStats] Send RT and Stored data continuous - All Data in Active Run and Surveys",
        rt_stored_type=adi.AdiEnums.DataTransferRtStoredType.RealtimeAndStored,
        transfer_mode=adi.AdiEnums.DataTransferMode.Continuous,
        datasets_type=adi.AdiEnums.DataTransferDatasetsType.SelectedDatasets,
        enable_config_change_notification=False, start_time=datetime.datetime.now(),
        restricted_records=["ADI Change Log", "ADI Event Log", "ADI Rec Mode", "Alarm Alert", "Alarm Client", "Alarm Data"]
    )
    # component.datasets.append(adi.AdiDefinitions.AdiDataSetPrimaryKey(well="25_11-HT-3Y1H", run_number=0, record="Desc Survey", description="Survey"))
    component.datasets.append(adi.AdiDefinitions.AdiDataSetPrimaryKey(well="25_11-HT-3Y1H", run_number=800))
    component.datasets.append(adi.AdiDefinitions.AdiDataSetPrimaryKey(well="25_11-HT-3Y1H", run_number=400, record="Survey", description="Imported Survey"))
    component.datasets.append(adi.AdiDefinitions.AdiDataSetPrimaryKey(well="25_11-HT-3Y1H", run_number=400, record="Survey", description="IFR Sag Corrected"))
    component.datasets.append(adi.AdiDefinitions.AdiDataSetPrimaryKey(well="25_11-HT-3Y1H", run_number=500, record="Survey", description="IFR Sag Corrected"))
    component.datasets.append(adi.AdiDefinitions.AdiDataSetPrimaryKey(well="25_11-HT-3Y1H", run_number=700, record="Survey", description="IFR Sag Corrected"))
    component.datasets.append(adi.AdiDefinitions.AdiDataSetPrimaryKey(well="25_11-HT-3Y1H", run_number=800, record="Survey", description="IFR Sag Corrected"))

    last_delete_succeeded = True
    while True:
        cmd = adi.AdiCommands.AdiCommands.DEX_Add(client=adi_client, component_dex=component)
        if last_delete_succeeded:
            response = await adi_client.SendNewCommand(cmd)

        cmd = adi.AdiCommands.AdiCommands.DEX_List(client=adi_client, full_details=True)
        response = await adi_client.SendNewCommand(cmd)

        cmd = adi.AdiCommands.AdiCommands.DEX_Remove(client=adi_client, hostname=component.remote_host, component_id=component.id)
        response = await adi_client.SendNewCommand(cmd)
        last_delete_succeeded = response["Success"]

        # print("\r\n\r\n".join([str(dex) for dex in response["DataExchanges"]]))
        await asyncio.sleep(1)

    await adi_client.Stop()

if __name__ == "__main__":
    asyncio.run(test_dex_list_command())
